#include "csapp.h"

jmp_buf buf;

void foo() {
  int *x = malloc(sizeof(int));
  *x = 10;
  longjmp(buf, 1);  // Jumps out of foo, skipping free(x)
  free(x); //This line will never be executed
}

int main() {
  if (setjmp(buf) == 0) {
    foo();
  }
  else {
    printf("Jumped back to main!\n");
  }
  return 0;
}
